const decodeEntities = (str) =>
  String(str || '')
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
    .replace(/<[^>]+>/g, ' ')
    .replace(/https?:\/\/\S+/gi, '')
    .replace(/\bwww\.\S+/gi, '')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;|&ldquo;|&rdquo;/gi, '"')
    .replace(/&#0?39;|&apos;|&rsquo;|&lsquo;/gi, "'")
    .replace(/&mdash;|&ndash;/gi, '—')
    .replace(/&hellip;/gi, '…')
    .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCharCode(parseInt(h, 16)))
    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)))
    .replace(/\s+/g, ' ')
    .trim();

const extractTag = (block, tags) => {
  for (const tag of tags) {
    const escaped = tag.replace(':', '\\:');
    const m = block.match(new RegExp(`<${escaped}(?:\\s[^>]*)?>([\\s\\S]*?)<\\/${escaped}>`, 'i'));
    if (m && m[1]) {
      const cleaned = decodeEntities(m[1]);
      if (cleaned) return cleaned;
    }
  }
  return '';
};

const extractLink = (block) => {
  const atomAlt = block.match(/<link[^>]+rel=["']alternate["'][^>]+href=["']([^"']+)["']/i)
    || block.match(/<link[^>]+href=["']([^"']+)["'][^>]+rel=["']alternate["']/i)
    || block.match(/<link[^>]+href=["']([^"']+)["']/i);
  if (atomAlt && atomAlt[1]) return atomAlt[1].trim();
  return extractTag(block, ['link']);
};

const parseFeed = (xml, sourceName) => {
  const entries = [];
  const blocks = [
    ...(String(xml || '').match(/<item\b[\s\S]*?<\/item>/gi) || []),
    ...(String(xml || '').match(/<entry\b[\s\S]*?<\/entry>/gi) || []),
  ];
  for (const b of blocks) {
    const title = extractTag(b, ['title']);
    const url = extractLink(b);
    const dateStr = extractTag(b, ['pubDate', 'published', 'updated', 'dc:date']);
    const summary = extractTag(b, ['description', 'summary', 'content:encoded', 'content']).slice(0, 420);
    const ts = dateStr ? Date.parse(dateStr) : 0;
    if (title) {
      entries.push({
        source: sourceName,
        title: title.length > 160 ? `${title.slice(0, 157)}…` : title,
        url: url || title,
        summary,
        ts: Number.isFinite(ts) ? ts : 0,
      });
    }
  }
  return entries;
};

const pickCategoryItems = (items) => {
  const now = Date.now();
  const cutoff = now - 7 * 24 * 3600 * 1000;
  const seen = new Set();
  const deduped = [];
  for (const it of items.sort((a, b) => b.ts - a.ts)) {
    const key = it.title.toLowerCase().replace(/[^a-z0-9à-ÿ]+/gi, ' ').trim();
    if (!key || seen.has(key) || seen.has(it.url)) continue;
    seen.add(key);
    seen.add(it.url);
    deduped.push(it);
  }
  let pool = deduped.filter((x) => x.ts >= cutoff);
  if (pool.length < 4) pool = deduped;

  const picked = [];
  const perSource = {};
  for (const it of pool) {
    if (picked.length >= 8) break;
    const c = perSource[it.source] || 0;
    if (c < 3) {
      picked.push(it);
      perSource[it.source] = c + 1;
    }
  }
  for (const it of pool) {
    if (picked.length >= 8) break;
    if (!picked.includes(it)) picked.push(it);
  }
  return picked;
};

const categories = [
  {
    key: 'ia',
    label: 'INTELLIGENCE ARTIFICIELLE',
    feeds: [
      { source: 'Hugging Face', url: 'https://huggingface.co/blog/feed.xml' },
      { source: 'OpenAI', url: 'https://openai.com/news/rss.xml' },
      { source: 'DeepMind', url: 'https://deepmind.google/blog/rss.xml' },
      { source: 'Simon Willison', url: 'https://simonwillison.net/atom/everything/' },
    ],
  },
  {
    key: 'cyber',
    label: 'CYBERSÉCURITÉ & CERT-FR',
    feeds: [
      { source: 'CERT-FR', url: 'https://www.cert.ssi.gouv.fr/feed/' },
      { source: 'The Hacker News', url: 'https://feeds.feedburner.com/TheHackersNews' },
      { source: 'BleepingComputer', url: 'https://www.bleepingcomputer.com/feed/' },
      { source: 'Krebs on Security', url: 'https://krebsonsecurity.com/feed/' },
    ],
  },
  {
    key: 'tech',
    label: 'INGÉNIERIE INFORMATIQUE, INFRA & TECH',
    feeds: [
      { source: 'InfoQ', url: 'https://feed.infoq.com/' },
      { source: 'Ars Technica', url: 'https://feeds.arstechnica.com/arstechnica/technology-lab' },
      { source: 'The Verge', url: 'https://www.theverge.com/rss/index.xml' },
      { source: 'TechCrunch', url: 'https://techcrunch.com/feed/' },
      { source: 'Korben', url: 'https://korben.info/feed' },
    ],
  },
];

const sections = [];
const counts = {};
const feedErrors = [];

for (const cat of categories) {
  const rawItems = [];
  for (const feed of cat.feeds) {
    try {
      const xml = await this.helpers.httpRequest({
        method: 'GET',
        url: feed.url,
        timeout: 10000,
        headers: {
          'User-Agent': 'Homelab-Veille-Bot/2.0',
          Accept: 'application/rss+xml, application/atom+xml, application/xml, text/xml',
        },
      });
      rawItems.push(...parseFeed(typeof xml === 'string' ? xml : JSON.stringify(xml), feed.source));
    } catch (_) {
      feedErrors.push(feed.source);
    }
  }
  const picked = pickCategoryItems(rawItems);
  counts[cat.key] = picked.length;
  const blockLines = [`=== ${cat.label} ===`];
  for (const it of picked) {
    const d = it.ts ? new Date(it.ts).toLocaleDateString('fr-FR', { day: '2-digit', month: '2-digit' }) : '--/--';
    blockLines.push(`- [${it.source} | ${d}] ${it.title}`);
    if (it.summary) blockLines.push(`  Extrait : ${it.summary}`);
  }
  sections.push(blockLines.join('\n'));
}

const dateLabel = new Date().toLocaleDateString('fr-FR', {
  timeZone: 'Europe/Paris',
  day: '2-digit',
  month: '2-digit',
  year: 'numeric',
});

const prompt = [
  `Nous sommes le ${dateLabel}. Tu es un journaliste et expert en ingénierie informatique qui prépare le briefing audio hebdomadaire d'Ethan (ingénieur en informatique spécialisé et curieux en IA, cybersécurité, génie logiciel et infrastructure).`,
  'Rédige en français UN SEUL monologue de podcast fluide, vivant, naturel et technique à écouter tel quel en version vocale, à partir uniquement des articles ci-dessous.',
  '',
  'Règles strictes :',
  '1. Retourne UNIQUEMENT un objet JSON valide avec exactement la clé : {"script": "..."}.',
  '2. Structure fluide du script audio :',
  '   - Courte introduction chaleureuse adressée à Ethan avec la date du briefing.',
  '   - Partie 1 — Intelligence Artificielle : 3 à 4 sujets clés expliquant concrètement les avancées modèles, agents, architectures, sécurité IA ou outillage pour ingénieurs.',
  '   - Partie 2 — Cybersécurité : 3 à 4 sujets critiques (avis CERT-FR, failles, campagnes d\'attaque, défense applicative ou système) avec l\'impact technique concret.',
  '   - Partie 3 — Ingénierie informatique, infra & tech : 3 à 4 actualités fortes sur l\'architecture logicielle, le cloud, le DevOps, les systèmes, l\'auto-hébergement ou les innovations majeures.',
  '   - Courte conclusion naturelle pour clôturer la semaine.',
  '3. Longueur IMPÉRATIVE pour tenir 2 minutes 30 à 3 minutes 30 à l\'oral : le champ "script" doit contenir entre 430 et 520 mots (STRICTEMENT au moins 410 mots). Développe clairement le contexte technique et le pourquoi de chaque sujet.',
  '4. Style 100 % parlé : phrases fluides et digestes à l\'oreille, transitions naturelles ("Côté intelligence artificielle...", "On passe maintenant à la cybersécurité...", "Enfin, pour l\'ingénierie informatique et la tech..."). Cite les noms des sources naturellement à l\'oral.',
  '5. INTERDICTION ABSOLUE d\'inclure : la moindre URL (http, https, www), puces, listes numérotées, markdown (**gras**, *italique*, #, `code`), emojis, ou didascalies entre parenthèses/crochets du type [pause] ou (jingle).',
  '6. Ne rien inventer en dehors des extraits fournis ci-dessous.',
  '',
  sections.join('\n\n'),
].join('\n');

const geminiBody = {
  contents: [{ role: 'user', parts: [{ text: prompt }] }],
  generationConfig: {
    responseMimeType: 'application/json',
    temperature: 0.4,
    maxOutputTokens: 8192,
    thinkingConfig: { thinkingBudget: 256 },
  },
};

return [{ json: { dateLabel, counts, feedErrors, geminiBody } }];

const resp = $input.first()?.json || {};
const parts = resp?.candidates?.[0]?.content?.parts || [];
const rawText = parts
  .filter((p) => !p.thought && typeof p.text === 'string')
  .map((p) => p.text)
  .join('')
  .trim();

if (!rawText) {
  throw new Error('Réponse Gemini script vide : ' + JSON.stringify(resp).slice(0, 400));
}

const jsonStr = rawText
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

const parsed = JSON.parse(jsonStr);
let script = String(parsed?.script || '')
  .replace(/\[([^\]]+)\]\((?:https?:\/\/|www\.)[^)]+\)/gi, '$1')
  .replace(/<?https?:\/\/[^\s>]+>?/gi, '')
  .replace(/\bwww\.[^\s>]+/gi, '')
  .replace(/\[(?:pause|jingle|musique|intro|outro|silence)[^\]]*\]/gi, ' ')
  .replace(/\((?:pause|jingle|musique|intro|outro|silence)[^)]*\)/gi, ' ')
  .replace(/[\*_`#•]+/g, '')
  .replace(/\s+/g, ' ')
  .trim();

const wordCount = script ? script.split(/\s+/).filter(Boolean).length : 0;
if (wordCount < 150) {
  throw new Error(`Script podcast trop court (${wordCount} mots) : ` + script.slice(0, 300));
}

const ttsBody = {
  contents: [{ role: 'user', parts: [{ text: script }] }],
  generationConfig: {
    responseModalities: ['AUDIO'],
    speechConfig: {
      voiceConfig: {
        prebuiltVoiceConfig: { voiceName: 'Aoede' },
      },
    },
  },
};

return [
  {
    json: {
      wordCount,
      charCount: script.length,
      script,
      ttsBody,
    },
  },
];

const resp = $input.first()?.json || {};
const parts = resp?.candidates?.[0]?.content?.parts || [];
const audioPart = parts.find((p) => p?.inlineData?.data);
if (!audioPart) {
  throw new Error('Gemini TTS sans audio : ' + JSON.stringify(resp).slice(0, 400));
}

const mime = String(audioPart.inlineData.mimeType || '');
const rateMatch = mime.match(/rate=(\d+)/i);
const sampleRate = rateMatch ? Number(rateMatch[1]) : 24000;

const conv = await this.helpers.httpRequest({
  method: 'POST',
  url: 'http://homelab-tts:8000/convert/pcm-to-opus',
  body: { pcm_base64: audioPart.inlineData.data, sample_rate: sampleRate },
  json: true,
  timeout: 60000,
});

if (!conv?.ogg_base64 || !conv?.size_bytes) {
  throw new Error('Conversion PCM -> OGG Opus invalide : ' + JSON.stringify(conv).slice(0, 300));
}

let wordCount = 0;
try {
  wordCount = $('Préparer Requête TTS').first()?.json?.wordCount || 0;
} catch (_) {}

return [
  {
    json: {
      ...conv,
      wordCount,
    },
  },
];

const prep = $('Convertir PCM -> OGG Opus').first().json;
const attResp = $('Discord Step 1 - Upload URL').first().json;
const att = attResp?.attachments?.[0];
if (!att?.upload_url || !att?.upload_filename) {
  throw new Error('Discord attachment URL manquante : ' + JSON.stringify(attResp).slice(0, 300));
}

const upRes = await this.helpers.httpRequest({
  method: 'POST',
  url: 'http://homelab-tts:8000/upload-ogg',
  body: { upload_url: att.upload_url, ogg_base64: prep.ogg_base64 },
  json: true,
  timeout: 60000,
});

if (!upRes || upRes.status < 200 || upRes.status >= 300) {
  throw new Error('Upload OGG échoué : ' + JSON.stringify(upRes));
}

return [
  {
    json: {
      uploaded_filename: att.upload_filename,
      duration_secs: prep.duration_secs,
      waveform: prep.waveform,
      size_bytes: prep.size_bytes,
      uploaded_bytes: upRes.uploaded_bytes,
      wordCount: prep.wordCount,
    },
  },
];
